class Report:
    def __init__(self, content): self.content = content
    def render(self): return self.content
class UpperMixin:
    def render(self): return super().render().upper()
class LoudReport(UpperMixin, Report): pass
def solve(data): return [LoudReport(s).render() for s in data]
